"""Auto-generated regression tests for bugs found during exploration.

Each test asserts the CORRECT behaviour, so it fails while the bug exists.
XFAIL = bug still present. XPASS = bug fixed -> remove the xfail marker.
Generated by bug_detector.py - regenerated on every run.
"""
from urllib.parse import urlparse

import pytest
from playwright.sync_api import TimeoutError as PlaywrightTimeoutError

STATIC_RESOURCE_TYPES = ("script", "stylesheet", "image", "font")
ERROR_TEXT_MARKERS = ('internal server error', 'traceback (most recent call last)', 'cannot get /', 'application error', 'unhandled runtime error', '502 bad gateway', '503 service unavailable')


def _same_host(url, host):
    return (urlparse(url).hostname or "").lower() == host


def _is_bad(response):
    status = response.status
    return (
        status >= 500
        or status == 404
        or (response.request.resource_type in STATIC_RESOURCE_TYPES and status >= 400)
    )


def _settle(page):
    try:
        page.wait_for_load_state("networkidle", timeout=5000)
    except PlaywrightTimeoutError:
        pass


@pytest.mark.bug
@pytest.mark.xfail(strict=False, reason='BUG001: Page returns HTTP 503')
def test_bug001_broken_page(page):
    response = page.goto('https://denqr.onrender.com/', wait_until="domcontentloaded")
    assert response is not None and response.status < 400, "Page did not load successfully"


